function Header() {
  return (
    <header>
      <nav>
        <a href="/">Home</a>
        <a href="/about">About</a>
      </nav>
    </header>
  );
}

function Sidebar() {
  return (
    <aside>
      <h3>Categories</h3>
      <ul>
        <li>React</li>
        <li>JavaScript</li>
        <li>TypeScript</li>
      </ul>
    </aside>
  );
}

function Footer() {
  return (
    <footer>
      <p>&copy; 2024 My App</p>
    </footer>
  );
}

function Page() {
  return (
    <div className="page">
      <Header />
      <div className="content">
        <main>
          <h1>Welcome to My App</h1>
          <p>This is the main content area.</p>
        </main>
        <Sidebar />
      </div>
      <Footer />
    </div>
  );
}

function Badge({ text, color }) {
  return <span className={`badge badge-${color}`}>{text}</span>;
}

function Price({ amount, currency = '$' }) {
  return <span className="price">{currency}{amount.toFixed(2)}</span>;
}

function AddToCartButton({ onClick }) {
  return (
    <button className="btn-primary" onClick={onClick}>
      Add to Cart
    </button>
  );
}

function ProductCard({ product }) {
  return (
    <div className="product-card">
      {product.isNew && <Badge text="New" color="green" />}
      <img src={product.image} alt={product.name} />
      <h3>{product.name}</h3>
      <p>{product.description}</p>
      <Price amount={product.price} />
      <AddToCartButton onClick={() => addToCart(product)} />
    </div>
  );
}

function ProductList({ products }) {
  return (
    <div className="product-list">
      {products.map((product) => (
        <ProductCard key={product.id} product={product} />
      ))}
    </div>
  );
}

// Usage
const products = [
  { id: 1, name: 'Laptop', price: 999.99, image: '/laptop.jpg', isNew: true },
  { id: 2, name: 'Phone', price: 699.99, image: '/phone.jpg', isNew: false },
  { id: 3, name: 'Tablet', price: 449.99, image: '/tablet.jpg', isNew: true },
];

<ProductList products={products} />
